solution.sum-column.sh:
#!/usr/bin/env bash
# sum-column.sh N : total of the integers in column N of the lines on standard input
case ${1:-} in
  ''|*[!0-9]*|0) echo "usage: sum-column.sh N   (N >= 1)" >&2; exit 2 ;;
esac
awk -v n="$1" '$n ~ /^-?[0-9]+$/ { total += $n } END { printf "%d\n", total }'

