EPOCH = 1700000000


def apply_tree(box, tree):
    later = []
    for path, ent in tree.items():
        full = os.path.join(box, path)
        t = ent.get("t", "f")
        if t == "h":
            later.append((full, ent))
            continue
        if t == "d":
            os.makedirs(full, exist_ok=True)
        elif t == "l":
